import com.sanctuarygames.createtransit.elevator.model.*;import java.nio.file.*;
public class ExportDoorStyles{
 static void uvs(StringBuilder b,java.util.List<CabinGeometry.Face> faces){b.append('[');for(int i=0;i<faces.size();i++){if(i>0)b.append(',');var f=faces.get(i);b.append('[').append(f.u0()).append(',').append(f.v0()).append(',').append(f.u1()).append(',').append(f.v1()).append(']');}b.append(']');}
 public static void main(String[] args)throws Exception{var root=Path.of(args[0]);Files.createDirectories(root);for(var style:CabinConfiguration.DoorStyle.values()){var p=CabinConfiguration.defaults(4,CabinConfiguration.Variant.SOLID).save();p.setProperty("doorStyle",style.name());p.setProperty("materialPrimary","minecraft:oak_planks");p.setProperty("materialSecondary","minecraft:gold_block");var c=CabinConfiguration.load(p);StringBuilder b=new StringBuilder("{\"style\":\"").append(style).append("\",\"closed\":");ExportCabinAssets.faces(b,CabinGeometry.landing(c,0));b.append(",\"open\":");ExportCabinAssets.faces(b,CabinGeometry.landing(c,1));b.append(",\"closedUV\":");uvs(b,CabinGeometry.landing(c,0));b.append(",\"openUV\":");uvs(b,CabinGeometry.landing(c,1));b.append(",\"sprites\":{");boolean first=true;for(var m:CabinGeometry.Material.values()){String id=DoorStyleTextures.sprite(style,m);if(id!=null){if(!first)b.append(',');first=false;b.append(ExportCabinAssets.quote(m.name())).append(':').append(ExportCabinAssets.quote(id));}}b.append("},\"materials\":[");for(int i=0;i<CabinGeometry.Material.values().length;i++){if(i>0)b.append(',');b.append('"').append(CabinGeometry.Material.values()[i]).append('"');}b.append("]}");Files.writeString(root.resolve(style.name()+".json"),b);}}
}
